curl_setopt($ch_download, CURLOPT_URL, $csv_download_url);
curl_setopt($ch_download, CURLOPT_RETURNTRANSFER, true);
curl_setopt($ch_download, CURLOPT_FOLLOWLOCATION, true);
curl_setopt($ch_download, CURLOPT_TIMEOUT, 30);

