#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Global buffer for "fast" access - a common early internet "optimization"
char global_scratch_pad[1024]; 

// Function to process a "request" - often involved dynamic allocation
char* process_request(const char* input_data) {
    // Allocate memory for the response. Early internet often didn't check for NULL.
    char* response = (char*)malloc(strlen(input_data) + 50); // +50 for "header" and "footer"

    // Copy input data. Buffer overflows were a feature, not a bug, for some.
    strcpy(response, "REQ: "); 
    strcat(response, input_data);
    strcat(response, " - END");

    // This function might return a pointer to dynamically allocated memory.
    // The caller is responsible for freeing it. This was a common pattern,
    // leading to many memory leaks.
    return response;
}

// Another function, demonstrating a different memory pattern
void log_message(const char* message) {
    // Using the global scratch pad. This avoids dynamic allocation but
    // introduces thread safety issues (if multi-threading was even a concept then)
    // and potential data corruption if not managed carefully.
    strncpy(global_scratch_pad, message, sizeof(global_scratch_pad) - 1);
    global_scratch_pad[sizeof(global_scratch_pad) - 1] = '\0'; // Ensure null termination

    printf("LOG: %s\n", global_scratch_pad);
}

// Main function - the orchestrator of memory chaos
int main() {
    // Scenario 1: Basic dynamic allocation and (hopefully) deallocation
    char* data1 = process_request("Hello World");
    printf("Response 1: %s\n", data1);
    free(data1); // Good, but often forgotten

    // Scenario 2: Memory leak - common in long-running servers
    char* data2 = process_request("Another Request");
    printf("Response 2 (leaked): %s\n", data2);
    // No free(data2) here. This memory is now lost until the program terminates.

    // Scenario 3: Using the global scratch pad
    log_message("System starting up...");
    log_message("Processing user input...");

    // Scenario 4: Potential buffer overflow (if input is too long)
    // This was often exploited or led to crashes.
    char long_input[2000];
    memset(long_input, 'A', sizeof(long_input) - 1);
    long_input[sizeof(long_input) - 1] = '\0';

    char* data3 = process_request(long_input); // This will likely overflow 'response'
    printf("Response 3 (overflowed?): %s\n", data3);
    free(data3); // Freeing potentially corrupted memory

